from google.cloud import secretmanager

class SecretManagerClient:
    def __init__(self):
        self.client = secretmanager.SecretManagerServiceClient()

    def get_secret_version_name(self, project_id: str, secret_id: str, version_id: str = "latest") -> str:
        return f"projects/{project_id}/secrets/{secret_id}/versions/{version_id}"

    def access_secret_version(self, name: str):
        response = self.client.access_secret_version(request={"name": name})
        return response

from google.cloud import translate

def runbook_translate(text_to_translate: str, target_language: str, project_id: str) -> dict:
    client = translate.TranslationServiceClient()
    location = "global"

    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_to_translate],
            "mime_type": "text/plain",  # Mime types: "text/plain" or "text/html"
            "target_language_code": target_language,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translated_text": translations[0] if translations else ""}
